<template><span class="file-name"><template v-if="keyword"><template v-for="(part,index) in parts" :key="index"><mark v-if="part.match">{{part.text}}</mark><template v-else>{{part.text}}</template></template></template><template v-else>{{base}}<span class="file-ext">{{ext}}</span></template><span v-if="item.favorite" class="file-star" aria-label="已收藏"><Icon name="star" class="small"/></span></span></template><script setup>import {computed} from 'vue';import {highlightSearchName} from '../../composables/drive/searchResults';import Icon from './Icon.vue';const props=defineProps({item:{type:Object,required:true},keyword:{default:''}});const dot=computed(()=>props.item.itemType==='folder'?-1:String(props.item.name||'').lastIndexOf('.'));const base=computed(()=>dot.value>0?props.item.name.slice(0,dot.value):props.item.name),ext=computed(()=>dot.value>0?props.item.name.slice(dot.value):'');const parts=computed(()=>highlightSearchName(props.item.name,props.keyword));</script>
